import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('Forms & Controlled Components', () => {
  test('Has name, email inputs and role select', async () => {
    const { container: root } = render(<App />);
    if (!root.querySelector('#name-input')) throw new Error('Missing #name-input');
if (!root.querySelector('#email-input')) throw new Error('Missing #email-input');
if (!root.querySelector('#role-select')) throw new Error('Missing #role-select');
  });

  test('Name input is controlled', async () => {
    const { container: root } = render(<App />);
    const input = root.querySelector('#name-input');
const nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
nativeInputValueSetter.call(input, 'Alice');
input.dispatchEvent(new Event('input', { bubbles: true }));
await tick();
if (input.value !== 'Alice') throw new Error('Input should be controlled and reflect typed value');
  });

  test('Summary not shown before submission', async () => {
    const { container: root } = render(<App />);
    const summary = root.querySelector('#summary');
if (summary) throw new Error('Summary should not be visible before submission');
  });

  test('Submitting form shows summary', async () => {
    const { container: root } = render(<App />);
    const nameInput = root.querySelector('#name-input');
const emailInput = root.querySelector('#email-input');
const nativeSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
nativeSetter.call(nameInput, 'Alice');
nameInput.dispatchEvent(new Event('input', { bubbles: true }));
await tick();
nativeSetter.call(emailInput, 'alice@test.com');
emailInput.dispatchEvent(new Event('input', { bubbles: true }));
await tick();
const btn = root.querySelector('#submit-btn');
const form = btn.closest('form');
if (!form) throw new Error('Submit button should be inside a <form>');
form.noValidate = true;
btn.click();
await tick();
await tick();
const summary = root.querySelector('#summary');
if (!summary) throw new Error('Summary should appear after submit');
if (!summary.textContent.includes('Alice')) throw new Error('Summary should include the name');
if (!summary.textContent.includes('alice@test.com')) throw new Error('Summary should include the email');
  });

  test('Role select has correct options', async () => {
    const { container: root } = render(<App />);
    const select = root.querySelector('#role-select');
const options = select.querySelectorAll('option');
const values = Array.from(options).map(o => o.value);
if (!values.includes('student')) throw new Error('Missing "student" option');
if (!values.includes('developer')) throw new Error('Missing "developer" option');
if (!values.includes('designer')) throw new Error('Missing "designer" option');
  });
});
